void F4SEAPI active_probe_message(F4SE::MessagingInterface::Message* message) {
    if (message == nullptr || message->sender == nullptr || std::strcmp(message->sender, "F4SE") != 0) {
        return;
    }
    if (message->type != F4SE::MessagingInterface::kGameLoaded &&
        message->type != F4SE::MessagingInterface::kPostLoadGame) {
        return;
    }
    if (message->type == F4SE::MessagingInterface::kPostLoadGame &&
        (message->data == nullptr || message->dataLen != sizeof(bool) ||
         !*static_cast<const bool*>(message->data))) {
        return;
    }

    const auto module = GetModuleHandleW(L"Fallout4.exe");
    if (module == nullptr) {
        log_line("active_probe experiment=actor-getlevel status=skipped reason=runtime-module-missing");
        log_line("active_probe experiment=actor-getsex status=skipped reason=runtime-module-missing");
        return;
    }
    const auto module_base = reinterpret_cast<std::uintptr_t>(module);
    const auto triggering_event =
        message->type == F4SE::MessagingInterface::kGameLoaded ? "kGameLoaded" : "kPostLoadGame";
    run_active_get_level_probe(module_base, triggering_event);
    run_active_get_sex_probe(module_base, triggering_event);
}

bool register_active_probe_listener(const F4SE::LoadInterface* load) noexcept {
    if (load == nullptr) {
        log_line("active_probe experiment=actor-getlevel status=disabled reason=load-interface-missing");
        log_line("active_probe experiment=actor-getsex status=disabled reason=load-interface-missing");
        return false;
    }
    // Use the raw F4SE 0.6.x interface here.  The pinned archive intentionally
    // contains CommonLib's shared runtime/relocation code, not its optional
    // high-level F4SE API adapter, so this keeps the diagnostic plugin's
    // messaging dependency explicit and linkable on Old-Gen.
    const auto* messaging = static_cast<const F4SE::Impl::F4SEMessagingInterface*>(
        load->QueryInterface(F4SE::LoadInterface::kMessaging));
    if (messaging == nullptr || messaging->interfaceVersion < F4SE::MessagingInterface::kVersion) {
        log_line("active_probe experiment=actor-getlevel status=disabled reason=messaging-interface-unavailable");
        log_line("active_probe experiment=actor-getsex status=disabled reason=messaging-interface-unavailable");
        return false;
    }
    const bool registered = messaging->RegisterListener(
        load->GetPluginHandle(),
        "F4SE",
        reinterpret_cast<void*>(&active_probe_message));
    log_line(
        registered
            ? "active_probe listener=registered experiments=actor-getlevel,actor-getsex events=kGameLoaded,kPostLoadGame"
            : "active_probe listener status=disabled experiments=actor-getlevel,actor-getsex reason=listener-registration-failed");
    return registered;
}

