# Lists top-level windows owned by the Fallout4 process with visibility/foreground state.
$source = @'
using System;
using System.Collections.Generic;
using System.Runtime.InteropServices;
using System.Text;

namespace Fo4MapWin
{
    public struct WindowInfo
    {
        public IntPtr Handle;
        public string Title;
        public string Class;
        public bool Visible;
        public int Width;
        public int Height;
    }

    public static class Enumerator
    {
        private delegate bool EnumWindowsProc(IntPtr hWnd, IntPtr lParam);

        [DllImport("user32.dll")]
        private static extern bool EnumWindows(EnumWindowsProc proc, IntPtr lParam);

        [DllImport("user32.dll")]
        private static extern uint GetWindowThreadProcessId(IntPtr hWnd, out uint pid);

        [DllImport("user32.dll", CharSet = CharSet.Unicode)]
        private static extern int GetWindowTextW(IntPtr hWnd, StringBuilder text, int count);

        [DllImport("user32.dll", CharSet = CharSet.Unicode)]
        private static extern int GetClassNameW(IntPtr hWnd, StringBuilder text, int count);

        [DllImport("user32.dll")]
        private static extern bool IsWindowVisible(IntPtr hWnd);

        [DllImport("user32.dll")]
        private static extern IntPtr GetForegroundWindow();

        [DllImport("user32.dll")]
        private static extern bool IsIconic(IntPtr hWnd);

        [DllImport("user32.dll")]
        private static extern bool GetClientRect(IntPtr hWnd, out RECT rect);

        [StructLayout(LayoutKind.Sequential)]
        private struct RECT { public int Left, Top, Right, Bottom; }

        public static WindowInfo[] ForProcess(uint targetPid)
        {
            List<WindowInfo> results = new List<WindowInfo>();
            EnumWindows((hWnd, lParam) =>
            {
                uint pid;
                GetWindowThreadProcessId(hWnd, out pid);
                if (pid != targetPid) return true;

                StringBuilder title = new StringBuilder(512);
                GetWindowTextW(hWnd, title, title.Capacity);
                StringBuilder cls = new StringBuilder(256);
                GetClassNameW(hWnd, cls, cls.Capacity);
                RECT rect;
                GetClientRect(hWnd, out rect);

                WindowInfo info = new WindowInfo();
                info.Handle = hWnd;
                info.Title = title.ToString();
                info.Class = cls.ToString();
                info.Visible = IsWindowVisible(hWnd);
                info.Width = rect.Right - rect.Left;
                info.Height = rect.Bottom - rect.Top;
                results.Add(info);
                return true;
            }, IntPtr.Zero);
            return results.ToArray();
        }

        public static IntPtr Foreground() { return GetForegroundWindow(); }

        public static bool Minimized(IntPtr hWnd) { return IsIconic(hWnd); }
    }
}
'@

if (-not ('Fo4MapWin.Enumerator' -as [type])) {
    Add-Type -TypeDefinition $source -Language CSharp
}

$proc = Get-Process -Name Fallout4 -ErrorAction SilentlyContinue | Select-Object -First 1
if (-not $proc) { throw 'Fallout4 process not found' }

$fg = [Fo4MapWin.Enumerator]::Foreground()
Write-Output "process=$($proc.Id) foreground=0x$('{0:X}' -f $fg.ToInt64())"
foreach ($w in [Fo4MapWin.Enumerator]::ForProcess([uint32]$proc.Id)) {
    Write-Output ("hwnd=0x{0:X} visible={1} iconic={2} size={3}x{4} class={5} title='{6}'" -f `
        $w.Handle.ToInt64(), $w.Visible, [Fo4MapWin.Enumerator]::Minimized($w.Handle), $w.Width, $w.Height, $w.Class, $w.Title)
}

