$source = @'
using System;
using System.Runtime.InteropServices;

namespace Fo4MapDiag
{
    [StructLayout(LayoutKind.Sequential)]
    public struct KEYBDINPUT
    {
        public ushort wVk;
        public ushort wScan;
        public uint dwFlags;
        public uint time;
        public IntPtr dwExtraInfo;
    }

    [StructLayout(LayoutKind.Explicit)]
    public struct INPUTUNION
    {
        [FieldOffset(0)] public KEYBDINPUT ki;
    }

    [StructLayout(LayoutKind.Sequential)]
    public struct INPUT
    {
        public uint type;
        public INPUTUNION u;
    }

    public static class Probe
    {
        [DllImport("user32.dll", SetLastError = true)]
        private static extern uint SendInput(uint nInputs, INPUT[] pInputs, int cbSize);

        [DllImport("user32.dll", SetLastError = true)]
        private static extern bool BlockInput(bool block);

        [DllImport("user32.dll")]
        private static extern IntPtr GetForegroundWindow();

        [DllImport("user32.dll")]
        private static extern uint GetWindowThreadProcessId(IntPtr hWnd, out uint pid);

        [DllImport("user32.dll", SetLastError = true)]
        private static extern uint GetWindowThreadProcessId2(IntPtr hWnd, IntPtr pid);

        [DllImport("kernel32.dll")]
        private static extern uint GetCurrentThreadId();

        [DllImport("user32.dll", SetLastError = true)]
        private static extern bool AttachThreadInput(uint idAttach, uint idAttachTo, bool fAttach);

        [DllImport("user32.dll", SetLastError = true)]
        private static extern IntPtr SetFocus(IntPtr hWnd);

        public static string Result = "";
        public static int LastError = 0;

        public static bool TrySend(uint keyCode)
        {
            INPUT[] down = new INPUT[1];
            down[0].type = 1;
            down[0].u.ki.wVk = (ushort)keyCode;
            down[0].u.ki.wScan = 0;
            down[0].u.ki.dwFlags = 0;
            uint r1 = SendInput(1, down, Marshal.SizeOf(typeof(INPUT)));
            LastError = Marshal.GetLastWin32Error();

            INPUT[] up = new INPUT[1];
            up[0].type = 1;
            up[0].u.ki.wVk = (ushort)keyCode;
            up[0].u.ki.wScan = 0;
            up[0].u.ki.dwFlags = 0x0002;
            uint r2 = SendInput(1, up, Marshal.SizeOf(typeof(INPUT)));

            Result = "down=" + r1 + " up=" + r2 + " size=" + Marshal.SizeOf(typeof(INPUT)) + " err=" + LastError;
            return r1 == 1 && r2 == 1;
        }

        public static string FocusInfo(IntPtr hWnd, out bool attached, out bool focused)
        {
            IntPtr fg = GetForegroundWindow();
            uint fgPid;
            uint fgThread = GetWindowThreadProcessId(fg, out fgPid);
            uint targetPid;
            uint targetThread = GetWindowThreadProcessId(hWnd, out targetPid);
            uint mine = GetCurrentThreadId();
            attached = AttachThreadInput(mine, fgThread, true);
            bool attachedTarget = AttachThreadInput(mine, targetThread, true);
            IntPtr previous = SetFocus(hWnd);
            focused = previous != IntPtr.Zero;
            AttachThreadInput(mine, targetThread, false);
            AttachThreadInput(mine, fgThread, false);
            return "fgThread=" + fgThread + " fgPid=" + fgPid + " targetThread=" + targetThread + " targetPid=" + targetPid +
                   " myThread=" + mine + " attachFg=" + attached + " attachTarget=" + attachedTarget;
        }
    }
}
