# Sends keyboard input to the Fallout 4 window through SendInput scan codes.
param(
    [Parameter(Mandatory = $true)][string]$Key,
    [int]$Count = 1,
    [int]$DelayMs = 300
)

$source = @'
using System;
using System.Runtime.InteropServices;

namespace Fo4MapInput
{
    [StructLayout(LayoutKind.Sequential)]
    public struct KEYBDINPUT
    {
        public ushort wVk;
        public ushort wScan;
        public uint dwFlags;
        public uint time;
        public IntPtr dwExtraInfo;
    }

    [StructLayout(LayoutKind.Explicit)]
    public struct INPUTUNION
    {
        [FieldOffset(0)] public KEYBDINPUT ki;
    }

    [StructLayout(LayoutKind.Sequential)]
    public struct INPUT
    {
        public uint type;
        public INPUTUNION u;
    }

    public static class Sender
    {
        [DllImport("user32.dll", SetLastError = true)]
        private static extern uint SendInput(uint nInputs, INPUT[] pInputs, int cbSize);

        [DllImport("user32.dll")]
        private static extern bool SetForegroundWindow(IntPtr hWnd);

        [DllImport("user32.dll")]
        private static extern IntPtr GetForegroundWindow();

        private const uint INPUT_KEYBOARD = 1;
        private const uint KEYEVENTF_KEYUP = 0x0002;
        private const uint KEYEVENTF_SCANCODE = 0x0008;

        public static void SendScan(ushort scan)
        {
            INPUT[] down = new INPUT[1];
            down[0].type = INPUT_KEYBOARD;
            down[0].u.ki.wVk = 0;
            down[0].u.ki.wScan = scan;
            down[0].u.ki.dwFlags = KEYEVENTF_SCANCODE;
            uint sentDown = SendInput(1, down, Marshal.SizeOf(typeof(INPUT)));

            INPUT[] up = new INPUT[1];
            up[0].type = INPUT_KEYBOARD;
            up[0].u.ki.wVk = 0;
            up[0].u.ki.wScan = scan;
            up[0].u.ki.dwFlags = KEYEVENTF_SCANCODE | KEYEVENTF_KEYUP;
            uint sentUp = SendInput(1, up, Marshal.SizeOf(typeof(INPUT)));

            if (sentDown != 1 || sentUp != 1)
            {
                throw new InvalidOperationException("SendInput did not deliver the keystroke");
            }
        }

        public static bool Focus(IntPtr hWnd)
        {
            if (hWnd == IntPtr.Zero) return false;
            if (GetForegroundWindow() == hWnd) return true;
            return SetForegroundWindow(hWnd);
        }
    }
}
'@

if (-not ('Fo4MapInput.Sender' -as [type])) {
    Add-Type -TypeDefinition $source -Language CSharp
}

$scans = @{
    ENTER = 0x1C
    ESCAPE = 0x01
    SPACE = 0x39
    DOWN = 0x50
    UP = 0x48
}
$scan = $scans[$Key.ToUpperInvariant()]
if (-not $scan) { throw "Unsupported key: $Key" }

$proc = Get-Process -Name Fallout4 -ErrorAction SilentlyContinue | Select-Object -First 1
if (-not $proc) { throw 'Fallout4 process not found' }

[void][Fo4MapInput.Sender]::Focus($proc.MainWindowHandle)
Start-Sleep -Milliseconds 400
for ($i = 0; $i -lt $Count; $i++) {
    [Fo4MapInput.Sender]::SendScan([uint16]$scan)
    Start-Sleep -Milliseconds $DelayMs
}
Write-Output "sent $Count x $Key scan=0x$('{0:X2}' -f $scan) to pid $($proc.Id) hwnd=$($proc.MainWindowHandle)"

