    SPACE = 0x39
    DOWN = 0x50
    UP = 0x48
}
$scan = $scans[$Key.ToUpperInvariant()]
if (-not $scan) { throw "Unsupported key: $Key" }

$proc = Get-Process -Name Fallout4 -ErrorAction SilentlyContinue | Select-Object -First 1
if (-not $proc) { throw 'Fallout4 process not found' }

[void][Fo4MapInput.Sender]::Focus($proc.MainWindowHandle)
Start-Sleep -Milliseconds 400
for ($i = 0; $i -lt $Count; $i++) {
    [Fo4MapInput.Sender]::SendScan([uint16]$scan)
    Start-Sleep -Milliseconds $DelayMs
}
Write-Output "sent $Count x $Key scan=0x$('{0:X2}' -f $scan) to pid $($proc.Id) hwnd=$($proc.MainWindowHandle)"

