$source = @'
using System;
using System.Drawing;
using System.Drawing.Imaging;
using System.Runtime.InteropServices;

namespace Fo4MapShot
{
    public static class Capture
    {
        [StructLayout(LayoutKind.Sequential)]
        private struct RECT { public int Left, Top, Right, Bottom; }

        [DllImport("user32.dll")]
        private static extern bool GetWindowRect(IntPtr hWnd, out RECT rect);

        [DllImport("user32.dll")]
        private static extern bool PrintWindow(IntPtr hWnd, IntPtr hdc, uint flags);

        public static bool Grab(IntPtr hWnd, string path)
        {
            RECT rect;
            if (!GetWindowRect(hWnd, out rect)) return false;
            int width = rect.Right - rect.Left;
            int height = rect.Bottom - rect.Top;
            if (width <= 0 || height <= 0) return false;
            using (Bitmap bitmap = new Bitmap(width, height, PixelFormat.Format24bppRgb))
            {
                using (Graphics graphics = Graphics.FromImage(bitmap))
                {
                    IntPtr hdc = graphics.GetHdc();
                    // PW_RENDERFULLCONTENT (0x2) captures DirectX surfaces that a
                    // plain BitBlt from the screen would miss when occluded.
                    bool ok = PrintWindow(hWnd, hdc, 0x2);
                    graphics.ReleaseHdc(hdc);
                    if (!ok)
                    {
                        graphics.CopyFromScreen(rect.Left, rect.Top, 0, 0, new Size(width, height), CopyPixelOperation.SourceCopy);
                    }
                }
                bitmap.Save(path, ImageFormat.Png);
            }
            return true;
        }
    }
}
'@

