arguments.content:
# Brings the Fallout 4 window to the foreground and captures it from the screen.
# Uses the AttachThreadInput technique because a background process cannot call
# SetForegroundWindow directly on Windows.
param(
    [Parameter(Mandatory = $true)][string]$Out,
    [switch]$NoFocus
)

$source = @'
using System;
using System.Drawing;
using System.Drawing.Imaging;
using System.Runtime.InteropServices;

namespace Fo4MapFocus
{
    [StructLayout(LayoutKind.Sequential)]
    public struct RECT { public int Left, Top, Right, Bottom; }

    public static class Window
    {
        [DllImport("user32.dll")]
        private static extern IntPtr GetForegroundWindow();

        [DllImport("user32.dll")]
        private static extern uint GetWindowThreadProcessId(IntPtr hWnd, IntPtr pid);

        [DllImport("kernel32.dll")]
        private static extern uint GetCurrentThreadId();

        [DllImport("user32.dll")]
        private static extern bool AttachThreadInput(uint idAttach, uint idAttachTo, bool fAttach);

        [DllImport("user32.dll")]
        private static extern bool SetForegroundWindow(IntPtr hWnd);

        [DllImport("user32.dll")]
        private static extern bool BringWindowToTop(IntPtr hWnd);

        [DllImport("user32.dll")]
        private static extern bool ShowWindow(IntPtr hWnd, int cmd);

        [DllImport("user32.dll")]
        private static extern bool GetWindowRect(IntPtr hWnd, out RECT rect);

        public static string Focus(IntPtr hWnd)
        {
            IntPtr foreground = GetForegroundWindow();
            uint foregroundThread = GetWindowThreadProcessId(foreground, IntPtr.Zero);
            uint mine = GetCurrentThreadId();
            bool attached = AttachThreadInput(mine, foregroundThread, true);
            ShowWindow(hWnd, 9);           // SW_RESTORE
            BringWindowToTop(hWnd);
            bool raised = SetForegroundWindow(hWnd);
            AttachThreadInput(mine, foregroundThread, false);
            System.Threading.Thread.Sleep(500);
