arguments.new_string:
public static bool Grab(IntPtr hWnd, string path, int cropLeft, int cropTop, int cropWidth, int cropHeight, int scale)
{
    RECT rect;
    if (!GetWindowRect(hWnd, out rect)) return false;
    int width = rect.Right - rect.Left;
    int height = rect.Bottom - rect.Top;
    if (width <= 0 || height <= 0) return false;
    using (Bitmap bitmap = new Bitmap(width, height, PixelFormat.Format24bppRgb))
    {
        using (Graphics graphics = Graphics.FromImage(bitmap))
        {
            graphics.CopyFromScreen(rect.Left, rect.Top, 0, 0, new Size(width, height), CopyPixelOperation.SourceCopy);
        }
        Bitmap output = bitmap;
        if (cropWidth > 0 && cropHeight > 0)
        {
            Rectangle region = new Rectangle(cropLeft, cropTop, Math.Min(cropWidth, width - cropLeft), Math.Min(cropHeight, height - cropTop));
            output = bitmap.Clone(region, PixelFormat.Format24bppRgb);
        }
        if (scale > 1)
        {
            Bitmap scaled = new Bitmap(output.Width * scale, output.Height * scale, PixelFormat.Format24bppRgb);
            using (Graphics graphics = Graphics.FromImage(scaled))
            {
                graphics.InterpolationMode = System.Drawing.Drawing2D.InterpolationMode.NearestNeighbor;
                graphics.DrawImage(output, 0, 0, scaled.Width, scaled.Height);
            }
            if (!ReferenceEquals(output, bitmap)) output.Dispose();
            output = scaled;
        }
        output.Save(path, ImageFormat.Png);
        if (!ReferenceEquals(output, bitmap)) output.Dispose();
    }
    return true;
}

