        [DllImport("user32.dll")]
        private static extern bool GetWindowRect(IntPtr hWnd, out RECT rect);

        public static string Focus(IntPtr hWnd)
        {
            IntPtr foreground = GetForegroundWindow();
            uint foregroundThread = GetWindowThreadProcessId(foreground, IntPtr.Zero);
            uint mine = GetCurrentThreadId();
            bool attached = AttachThreadInput(mine, foregroundThread, true);
            ShowWindow(hWnd, 9);           // SW_RESTORE
            BringWindowToTop(hWnd);
            bool raised = SetForegroundWindow(hWnd);
            AttachThreadInput(mine, foregroundThread, false);
            System.Threading.Thread.Sleep(500);
            IntPtr now = GetForegroundWindow();
            return "raised=" + raised + " attached=" + attached + " foreground=0x" + now.ToInt64().ToString("X") +
                   " target=0x" + hWnd.ToInt64().ToString("X") + " isTarget=" + (now == hWnd);
        }

