                        graphics.DrawImage(output, 0, 0, scaled.Width, scaled.Height);
                    }
                    if (!ReferenceEquals(output, bitmap)) output.Dispose();
                    output = scaled;
                }
                output.Save(path, ImageFormat.Png);
