param(
    [Parameter(Mandatory = $true)]
    [string]$GhidraHome,
    [Parameter(Mandatory = $true)]
    [string]$Image,
    [Parameter(Mandatory = $true)]
    [string]$BundleManifest,
    [Parameter(Mandatory = $true)]
    [string]$ProjectDirectory,
    [string]$ProjectName = 'Fallout4Mapping',
    [switch]$NoAnalysis,
    [string]$PyGhidraPython,
    [int]$XrefLimit = 0
)

$headless = Join-Path $GhidraHome 'support\analyzeHeadless.bat'
$pyghidraLauncher = Join-Path $GhidraHome 'Ghidra\Features\PyGhidra\support\pyghidra_launcher.py'
$scriptDirectory = Split-Path -Parent $PSCommandPath
if (-not (Test-Path -LiteralPath $headless)) {
    throw "Ghidra headless launcher was not found: $headless"
}
if (-not (Test-Path -LiteralPath $Image)) {
    throw "analysis image was not found: $Image"
}
if (-not (Test-Path -LiteralPath $BundleManifest)) {
    throw "semantic bundle manifest was not found: $BundleManifest"
}
if ($PyGhidraPython -and -not (Test-Path -LiteralPath $PyGhidraPython)) {
    throw "PyGhidra Python executable was not found: $PyGhidraPython"
}
if ($PyGhidraPython -and -not (Test-Path -LiteralPath $pyghidraLauncher)) {
    throw "Ghidra PyGhidra launcher was not found: $pyghidraLauncher"
}
if ($XrefLimit -lt 0) {
    throw "XrefLimit must be zero (unlimited) or a positive row count"
}

$projectRoot = [System.IO.Path]::GetFullPath($ProjectDirectory)
if (Test-Path -LiteralPath $projectRoot) {
    if (-not (Get-Item -LiteralPath $projectRoot).PSIsContainer) {
        throw "Ghidra project directory is not a directory: $projectRoot"
    }
} else {
    New-Item -ItemType Directory -Path $projectRoot -Force | Out-Null
}

$resolvedImage = (Resolve-Path -LiteralPath $Image).Path
$resolvedManifest = (Resolve-Path -LiteralPath $BundleManifest).Path
$bundleDirectory = Split-Path -Parent $resolvedManifest
$manifest = Get-Content -LiteralPath $resolvedManifest -Raw | ConvertFrom-Json
$expectedHash = ([string]$manifest.image.sha256).ToUpperInvariant()
if ($expectedHash -notmatch '^[0-9A-F]{64}$') {
    throw "semantic bundle manifest does not contain a valid image SHA-256"
}
$actualHash = (Get-FileHash -LiteralPath $resolvedImage -Algorithm SHA256).Hash.ToUpperInvariant()
if ($actualHash -ne $expectedHash) {
    throw "analysis image SHA-256 mismatch: actual=$actualHash expected=$expectedHash"
}

$validator = Join-Path $scriptDirectory 'validate_semantic_bundle.py'
$python = Get-Command py -ErrorAction SilentlyContinue
if ($null -eq $python) {
    throw "Python launcher 'py' is required to validate the semantic bundle"
}
& $python.Path -3 $validator --bundle $bundleDirectory
if ($LASTEXITCODE -ne 0) {
    throw "semantic bundle validation failed with exit code $LASTEXITCODE"
}

$headlessArguments = @(
    $projectRoot,
    $ProjectName,
    '-import', $resolvedImage,
    '-overwrite'
)
if ($NoAnalysis) {
    $headlessArguments += '-noanalysis'
}
$headlessArguments += @(
    '-scriptPath', $scriptDirectory,
    '-postScript', 'ghidra_import_map.py', $resolvedManifest
)
if ($XrefLimit -gt 0) {
    $headlessArguments += [string]$XrefLimit
}
$headlessOutput = if ($PyGhidraPython) {
    @(& $PyGhidraPython $pyghidraLauncher $GhidraHome '--headless' '--console' @headlessArguments 2>&1)
} else {
    @(& $headless @headlessArguments 2>&1)
}
$headlessExitCode = $LASTEXITCODE
$headlessOutput | ForEach-Object { $_ }
if ($headlessExitCode -ne 0) {
    throw "Ghidra headless import failed with exit code $headlessExitCode"
}
$scriptFailures = @($headlessOutput | ForEach-Object { [string]$_ } | Where-Object {
        $_ -match '(?i)SCRIPT ERROR|Python is not available|Traceback \(most recent call last\)'
    })
if ($scriptFailures.Count -gt 0) {
    throw "Ghidra headless script failed even though the launcher returned success: $($scriptFailures -join ' | ')"
}
