arguments.content:
# Clicks once inside the Fallout 4 window using absolute SendInput mouse events.
param(
    [Parameter(Mandatory = $true)][int]$X,   # window-rect-relative X
    [Parameter(Mandatory = $true)][int]$Y    # window-rect-relative Y
)

$source = @'
using System;
using System.Runtime.InteropServices;

namespace Fo4MapClick
{
    [StructLayout(LayoutKind.Sequential)]
    public struct RECT { public int Left, Top, Right, Bottom; }

    [StructLayout(LayoutKind.Sequential)]
    public struct MOUSEINPUT
    {
        public int dx;
        public int dy;
        public uint mouseData;
        public uint dwFlags;
        public uint time;
        public IntPtr dwExtraInfo;
    }

    [StructLayout(LayoutKind.Sequential)]
    public struct KEYBDINPUT
    {
        public ushort wVk;
        public ushort wScan;
        public uint dwFlags;
        public uint time;
        public IntPtr dwExtraInfo;
    }

    [StructLayout(LayoutKind.Sequential)]
    public struct HARDWAREINPUT
    {
        public uint uMsg;
        public ushort wParamL;
        public ushort wParamH;
    }

    [StructLayout(LayoutKind.Explicit)]
    public struct INPUTUNION
    {
        [FieldOffset(0)] public MOUSEINPUT mi;
        [FieldOffset(0)] public KEYBDINPUT ki;
        [FieldOffset(0)] public HARDWAREINPUT hi;
    }

    [StructLayout(LayoutKind.Sequential)]
    public struct INPUT
    {
        public uint type;
        public INPUTUNION u;
    }

    public static class Clicker
    {
        [DllImport("user32.dll")]
        private static extern bool GetWindowRect(IntPtr hWnd, out RECT rect);

        [DllImport("user32.dll", SetLastError = true)]
        private static extern uint SendInput(uint nInputs, INPUT[] pInputs, int cbSize);

        [DllImport("user32.dll")]
        private static extern int GetSystemMetrics(int index);

        [DllImport("user32.dll")]
        private static extern IntPtr GetForegroundWindow();

        [DllImport("user32.dll")]
        private static extern bool SetForegroundWindow(IntPtr hWnd);

        private const uint INPUT_MOUSE = 0;
        private const uint MOUSEEVENTF_MOVE = 0x0001;
        private const uint MOUSEEVENTF_ABSOLUTE = 0x8000;
        private const uint MOUSEEVENTF_LEFTDOWN = 0x0002;
        private const uint MOUSEEVENTF_LEFTUP = 0x0004;

        public static string Click(IntPtr hWnd, int offsetX, int offsetY)
        {
            RECT rect;
            if (!GetWindowRect(hWnd, out rect)) return "GetWindowRect failed";
            SetForegroundWindow(hWnd);
            System.Threading.Thread.Sleep(400);

            int screenX = rect.Left + offsetX;
            int screenY = rect.Top + offsetY;
            int screenWidth = GetSystemMetrics(0);   // SM_CXSCREEN
            int screenHeight = GetSystemMetrics(1);  // SM_CYSCREEN
            int normX = (int)((screenX * 65535L) / (screenWidth - 1));
            int normY = (int)((screenY * 65535L) / (screenHeight - 1));

            INPUT[] inputs = new INPUT[3];
            inputs[0].type = INPUT_MOUSE;
            inputs[0].u.mi.dx = normX;
            inputs[0].u.mi.dy = normY;
            inputs[0].u.mi.dwFlags = MOUSEEVENTF_MOVE | MOUSEEVENTF_ABSOLUTE;
            inputs[1].type = INPUT_MOUSE;
            inputs[1].u.mi.dx = normX;
            inputs[1].u.mi.dy = normY;
            inputs[1].u.mi.dwFlags = MOUSEEVENTF_MOVE | MOUSEEVENTF_ABSOLUTE | MOUSEEVENTF_LEFTDOWN;
            inputs[2].type = INPUT_MOUSE;
            inputs[2].u.mi.dx = normX;
            inputs[2].u.mi.dy = normY;
            inputs[2].u.mi.dwFlags = MOUSEEVENTF_MOVE | MOUSEEVENTF_ABSOLUTE | MOUSEEVENTF_LEFTUP;

            uint sent = SendInput(3, inputs, Marshal.SizeOf(typeof(INPUT)));
            return "sent=" + sent + " cursor=(" + screenX + "," + screenY + ") foreground=" +
                   (GetForegroundWindow() == hWnd);
        }
    }
}
'@

if (-not ('Fo4MapClick.Clicker' -as [type])) {
    Add-Type -TypeDefinition $source -Language CSharp
}

$proc = Get-Process -Name Fallout4 -ErrorAction SilentlyContinue | Select-Object -First 1
if (-not $proc) { throw 'Fallout4 process not found' }
Write-Output ([Fo4MapClick.Clicker]::Click($proc.MainWindowHandle, $X, $Y))

