    except (TypeError, ValueError) as exc:
        raise ValueError("active non-mutating observation has invalid address evidence") from exc
    if function_address - module_base != function_rva:
        raise ValueError("active non-mutating observation function address does not match RVA and module base")
    if item.get("return_value") is None:
        raise ValueError("active non-mutating observation must record a return value")


def import_dynamic_evidence(
    database: str | Path,
    evidence_path: str | Path,
    *,
    image_id: int | None = None,
    replace: bool = False,
    replace_source: bool = False,
) -> dict[str, object]:
    db_path = Path(database).resolve()
    source = Path(evidence_path).resolve()
    payload = json.loads(source.read_text(encoding="utf-8"))
    if not isinstance(payload, dict) or str(payload.get("schema_version", "")) != SCHEMA_VERSION:
        raise ValueError("dynamic evidence manifest has an unsupported schema version")
    experiments = payload.get("experiments", [payload])
    if not isinstance(experiments, list):
        raise ValueError("dynamic evidence experiments must be an array")

    connection = sqlite3.connect(db_path)
    connection.row_factory = sqlite3.Row
    connection.execute("PRAGMA foreign_keys = ON")
    try:
        images = connection.execute(
            "SELECT image_id,runtime_version,sha256,image_size FROM images ORDER BY image_id"
        ).fetchall()
        if image_id is not None:
            image = next((row for row in images if int(row[0]) == image_id), None)
            if image is None:
                raise ValueError(f"research database has no image_id={image_id}")
        elif len(images) == 1:
            image = images[0]
        elif not images:
            raise ValueError("research database contains no image")
        else:
            raise ValueError("dynamic evidence import requires --image-id for a multi-image database")
        runtime = payload.get("runtime", {})
        if not isinstance(runtime, dict):
            raise ValueError("dynamic evidence runtime must be an object")
        if str(runtime.get("version", "")) != str(image[1]):
            raise ValueError("dynamic evidence runtime does not match the database image")
        # A live Fallout 4 run may validate a protected on-disk executable
        # while the research DB is indexed by the matching unpacked analysis
        # image.  Preserve the historical ``sha256`` field for the DB image,
        # and allow the manifest to carry the protected file identity
        # separately without weakening the database-image check.
        for key in ("sha256", "analysis_image_sha256", "executable_sha256"):
            if key in runtime and runtime[key] is not None:
                value = str(runtime[key]).strip()
                if len(value) != 64 or any(character not in "0123456789abcdefABCDEF" for character in value):
                    raise ValueError(f"dynamic evidence runtime {key} must be a SHA-256 hex string")
        analysis_image_sha256 = runtime.get("analysis_image_sha256", runtime.get("sha256", ""))
        if str(analysis_image_sha256).upper() != str(image[2]).upper():
            raise ValueError("dynamic evidence analysis-image SHA-256 does not match the database image")

        source_metadata_key = f"dynamic_evidence_source:{int(image[0])}"
        if replace_source:
            previous_source = connection.execute(
                "SELECT value FROM schema_metadata WHERE key=?",
                (source_metadata_key,),
            ).fetchone()
            if previous_source is None:
                # Databases created before per-image source provenance used a
                # single metadata key.  Use it only as a compatibility hint;
                # refusing a mismatch is safer than deleting another source's
                # evidence when upgrading a multi-image database.
                previous_source = connection.execute(
                    "SELECT value FROM schema_metadata WHERE key='dynamic_evidence_source'"
                ).fetchone()
            if previous_source is not None and Path(str(previous_source[0])).resolve() != source:
                raise ValueError(
                    "dynamic evidence source replacement would remove evidence from a different source"
                )
            # This is deliberately image-scoped.  A research database may hold
            # more than one runtime image, and source replacement must not
            # affect evidence belonging to another image.
            connection.execute(
                "DELETE FROM dynamic_evidence WHERE image_id=?",
                (int(image[0]),),
            )

        inserted = 0
        for item in experiments:
            if not isinstance(item, dict):
                raise ValueError("each dynamic evidence item must be an object")
            required = (
                "experiment_id", "function_rva", "triggering_action", "thread", "registers",
                "arguments", "observations", "return_value", "call_targets", "observed_at",
                "plugin_build", "reproducibility",
            )
            missing = [
                key for key in required
                if key not in item or (item[key] is None and key != "return_value")
            ]
            for key in (
                "experiment_id", "function_rva", "triggering_action", "thread", "observed_at",
                "plugin_build", "reproducibility",
            ):
                if key in item and not str(item[key]).strip():
                    missing.append(key)
            missing = list(dict.fromkeys(missing))
            if missing:
                raise ValueError(f"dynamic evidence item is missing: {', '.join(missing)}")
            for key in ("registers", "arguments", "observations"):
                if not isinstance(item[key], dict):
                    raise ValueError(f"dynamic evidence item {key} must be an object")
            if not isinstance(item["call_targets"], list):
                raise ValueError("dynamic evidence item call_targets must be an array")
            _validate_active_nonmutating_observation(item)
            function_rva = int(str(item["function_rva"]), 0)
            if function_rva < 0 or function_rva >= int(image[3]):
                raise ValueError(
                    f"dynamic evidence function RVA is outside the image: 0x{function_rva:X}"
                )
            if replace:
                connection.execute(
                    "DELETE FROM dynamic_evidence WHERE image_id=? AND experiment_id=?",
                    (int(image[0]), str(item["experiment_id"])),
                )
            connection.execute(
                """
                INSERT INTO dynamic_evidence(
                    image_id,experiment_id,function_rva,triggering_action,thread,
                    registers_json,arguments_json,observations_json,return_value,
                    call_targets_json,observed_at,plugin_build,reproducibility,confidence
                ) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?)
                """,
                (
                    int(image[0]),
                    str(item["experiment_id"]),
                    function_rva,
                    str(item["triggering_action"]),
                    str(item["thread"]) if item.get("thread") else None,
                    json.dumps(item.get("registers", {}), sort_keys=True),
                    json.dumps(item.get("arguments", {}), sort_keys=True),
                    json.dumps(item.get("observations", {}), sort_keys=True),
                    str(item["return_value"]) if item.get("return_value") is not None else None,
                    json.dumps(item.get("call_targets", []), sort_keys=True),
                    str(item["observed_at"]),
                    str(item["plugin_build"]),
                    str(item["reproducibility"]),
                    str(item.get("confidence", "tentative")),
                ),
            )
            inserted += 1
        connection.executemany(
            "INSERT OR REPLACE INTO schema_metadata(key,value) VALUES (?,?)",
            (
                ("dynamic_evidence_source", str(source)),
                (source_metadata_key, str(source)),
                ("dynamic_evidence_importer", PIPELINE_VERSION),
            ),
        )
        connection.commit()
        report: dict[str, object] = {
            "schema_version": SCHEMA_VERSION,
            "tool": PIPELINE_VERSION,
            "database": str(db_path),
…
        }
        return report
