def _import_reviewed_abi(bundle, image_base):
    """Apply the small source-reviewed ABI set and annotate its provenance."""
    entry_rvas = {}
    for row in _rows(bundle, "functions.csv"):
        logical_id = row.get("logical_function_id")
        entry_rva = _integer(row.get("entry_rva"))
        if logical_id and entry_rva is not None:
            entry_rvas[str(logical_id)] = entry_rva

    imported = 0
    skipped = 0
    for row in _rows(bundle, "abi_signatures.csv"):
