# --- allocation sizes and embedded vptr stores -------------------
# Window state: the immediate constants currently live in the
# argument registers, the allocation call one of them fed, and the
# registers proven to hold that allocation's return value.
#
# MSVC's operator new takes the size in rcx, but pooled and
# aligned allocators take it in rdx/r8/r9, so the window tracks
# every argument register and records which one carried the size.
pending_immediates: dict[str, tuple[int, int]] = {}
pending_allocation_rva: int | None = None
allocation_size: int | None = None
allocation_size_rva: int | None = None
allocation_size_register: str | None = None
allocation_registers: set[str] = set()

def _reset_window() -> None:
    pending_immediates.clear()
    _clear_allocation()

def _clear_allocation() -> None:
    nonlocal pending_allocation_rva, allocation_size
    nonlocal allocation_size_rva, allocation_size_register
    pending_allocation_rva = None
    allocation_size = None
    allocation_size_rva = None
    allocation_size_register = None
    allocation_registers.clear()

def _nearest_immediate() -> tuple[str, int, int] | None:
    if not pending_immediates:
        return None
    register, (immediate, index) = max(
        pending_immediates.items(), key=lambda item: item[1][1]
    )
    return register, immediate, index

for index, instruction in enumerate(instructions):
    mnemonic = instruction.mnemonic
    operands = instruction.operands
    consumed_immediate = False

    if mnemonic == "mov" and len(operands) == 2 and operands[0].type == CS_OP_REG:
        destination = instruction.reg_name(operands[0].reg)
        source = operands[1]
        if source.type == CS_OP_IMM:
            immediate = int(source.imm)
            if (
                pending_allocation_rva is None
                and destination in ARGUMENT_REGISTERS
                and 0 < immediate < 0x10000000
            ):
                pending_immediates[_canonical_argument_register(destination)] = (
                    immediate,
                    index,
                )
                consumed_immediate = True
        elif source.type == CS_OP_REG and pending_allocation_rva is not None:
            source_register = instruction.reg_name(source.reg)
            if source_register == "rax" or source_register in allocation_registers:
                allocation_registers.add(_canonical_argument_register(destination))

    if (
        not consumed_immediate
        and pending_allocation_rva is None
        and pending_immediates
    ):
        # Any other write to an argument register invalidates the
        # constant it held.
        for candidate in operands:
            if candidate.type == CS_OP_REG and candidate.access & capstone.CS_AC_WRITE:
                pending_immediates.pop(
                    _canonical_argument_register(instruction.reg_name(candidate.reg)),
                    None,
                )

    if mnemonic == "call" and operands and operands[0].type == CS_OP_IMM:
        target_rva = int(operands[0].imm - image.image_base)
        call_rva = int(instruction.address - image.image_base)
        if pending_allocation_rva is None:
            nearest = _nearest_immediate()
            if nearest is not None and call_rva - _immediate_rva(
                instructions, nearest[2], image
            ) <= ALLOCATION_SIZE_WINDOW:
                allocation_size_register, allocation_size, _ = nearest
                allocation_size_rva = _immediate_rva(instructions, nearest[2], image)
                pending_allocation_rva = call_rva
            else:
                _reset_window()
        elif (
            allocation_size is not None
            and "rcx" in allocation_registers
            and target_rva in ctor_class_by_rva
            and call_rva - pending_allocation_rva <= CTOR_LOOKAHEAD_AFTER_ALLOCATION
        ):
            # The constructor is called on the fresh allocation.
            allocation_sizes[ctor_class_by_rva[target_rva]].append(
                {
                    "size_bytes": allocation_size,
                    "size_rva": allocation_size_rva,
                    "size_register": allocation_size_register,
                    "allocation_rva": pending_allocation_rva,
                    "allocator_rva": allocator_at.get(pending_allocation_rva),
                    "constructor_rva": target_rva,
                    "constructor_call_rva": call_rva,
                }
            )
            counts["allocation_chains"] += 1
            _reset_window()
        else:
            _reset_window()
        # A call destroys every volatile register.
        for register in list(pending_immediates):
            if register in VOLATILE_REGISTERS:
                pending_immediates.pop(register, None)
        allocation_registers.difference_update(VOLATILE_REGISTERS)
    elif mnemonic in {"ret", "leave"}:
        _reset_window()

