from __future__ import annotations

from pathlib import Path
import sys
import unittest

import capstone

TOOLS = Path(__file__).resolve().parents[1] / "tools"
sys.path.insert(0, str(TOOLS))

from infer_class_layouts import (  # noqa: E402
    _canonical_argument_register,
    _class_from_demangled,
    _is_constructor_of,
    _member_name,
)


def _disassemble(code: bytes, address: int = 0x140001000) -> list:
    decoder = capstone.Cs(capstone.CS_ARCH_X86, capstone.CS_MODE_64)
    decoder.detail = True
    decoder.syntax = capstone.CS_OPT_SYNTAX_INTEL
    return list(decoder.disasm(code, address))


class ClassLayoutIdentityTests(unittest.TestCase):
    def test_constructor_identity_requires_matching_leaf(self) -> None:
        self.assertEqual(_is_constructor_of("Actor::Actor(bool)"), ("Actor", "Actor"))
        self.assertEqual(_is_constructor_of("Actor::~Actor(void)"), ("Actor", "~Actor"))
        # A method whose leaf differs from its owner is not a constructor.
        self.assertIsNone(_is_constructor_of("Actor::GetLevel(void)"))

    def test_owner_is_taken_from_demangled_symbol(self) -> None:
        self.assertEqual(_class_from_demangled("Actor::Actor(bool)"), "Actor")
        self.assertEqual(
            _class_from_demangled("BSScript::NF_util::NativeFunctionBase::NativeFunctionBase(void)"),
            "BSScript::NF_util::NativeFunctionBase",
        )
        self.assertIsNone(_class_from_demangled(None))

    def test_recovered_member_names_are_never_declared_names(self) -> None:
        # A recovered offset must not pretend to be a CommonLibF4 field name.
        self.assertEqual(_member_name(0x110, vptr=False), "member_0x110")
        self.assertEqual(_member_name(0x20, vptr=True), "__vfptr_0x20")

    def test_argument_register_aliases_collapse_to_64_bit(self) -> None:
        self.assertEqual(_canonical_argument_register("ecx"), "rcx")
        self.assertEqual(_canonical_argument_register("r8d"), "r8")
        self.assertEqual(_canonical_argument_register("rbx"), "rbx")


class ObjectRegisterTrackingTests(unittest.TestCase):
    """A memory load into a register must end its object-pointer alias.

    The recovery pass reads the most-derived class out of a vtable store
    after a constructor call.  If a register that merely *used* to hold the
    object keeps its alias after being reloaded from memory, an unrelated
    store is attributed to the allocation and a wrong size is recorded.
    """

    def test_reloaded_register_is_not_the_object(self) -> None:
        # mov rcx, rax ; mov rcx, [rsp+0x20] ; mov [rcx], rdx
        code = bytes.fromhex(
            "48 8B C8"          # mov rcx, rax
            "48 8B 4C 24 20"    # mov rcx, [rsp+0x20]
            "48 89 11"          # mov [rcx], rdx
        )
        instructions = _disassemble(code)
        object_registers = {"rax"}
        stored_through_object = False
        for instruction in instructions:
            operands = instruction.operands
            if instruction.mnemonic == "mov" and len(operands) == 2 and operands[0].type == capstone.x86.X86_OP_REG:
                destination = instruction.reg_name(operands[0].reg)
                source = operands[1]
                if source.type == capstone.x86.X86_OP_REG:
                    if instruction.reg_name(source.reg) in object_registers:
                        object_registers.add(destination)
                    else:
                        object_registers.discard(destination)
                elif source.type == capstone.x86.X86_OP_MEM:
                    object_registers.discard(destination)
                continue
            if instruction.mnemonic == "mov" and operands and operands[0].type == capstone.x86.X86_OP_MEM:
                base = instruction.reg_name(operands[0].mem.base)
                if base in object_registers and int(operands[0].mem.disp) == 0:
                    stored_through_object = True
        self.assertFalse(stored_through_object)

    def test_call_destroys_volatile_object_aliases(self) -> None:
        # mov rdx, rax ; call rax ; mov [rdx], rbx
        code = bytes.fromhex(
            "48 89 C2"          # mov rdx, rax
            "FF D0"             # call rax
            "48 89 1A"          # mov [rdx], rbx
        )
        instructions = _disassemble(code)
        object_registers = {"rax"}
        stored_through_object = False
        for instruction in instructions:
            operands = instruction.operands
            if instruction.mnemonic == "call":
                object_registers.difference_update({"rax", "rcx", "rdx", "r8", "r9", "r10", "r11"})
                continue
            if instruction.mnemonic == "mov" and len(operands) == 2 and operands[0].type == capstone.x86.X86_OP_REG:
                destination = instruction.reg_name(operands[0].reg)
                source = operands[1]
                if source.type == capstone.x86.X86_OP_REG:
                    if instruction.reg_name(source.reg) in object_registers:
                        object_registers.add(destination)
                    else:
                        object_registers.discard(destination)
                continue
            if instruction.mnemonic == "mov" and operands and operands[0].type == capstone.x86.X86_OP_MEM:
                base = instruction.reg_name(operands[0].mem.base)
                if base in object_registers and int(operands[0].mem.disp) == 0:
                    stored_through_object = True
        self.assertFalse(stored_through_object)


if __name__ == "__main__":
    unittest.main()

