// FNV-1a over the observation stream.  This is an integrity digest of what
// the run observed, not a cryptographic commitment.
std::uint64_t fnv1a(std::uint64_t digest, std::uint64_t value) noexcept {
    for (int index = 0; index < 8; ++index) {
        digest ^= static_cast<std::uint8_t>((value >> (index * 8)) & 0xFFu);
        digest *= 1099511628211ULL;
    }
    return digest;
}

void read_bounded_string(const char* text, char (&output)[64]) noexcept {
    output[0] = '\0';
    if (text == nullptr) {
        return;
    }
    for (std::size_t index = 0; index + 1 < std::size(output); ++index) {
        const char character = text[index];
        if (character == '\0') {
            break;
        }
        output[index] = character;
        output[index + 1] = '\0';
    }
}

