const ctx = globalThis.beh;
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const lines = () => readFileSync(ctx.LOG, "utf8").split(/\r?\n/);
const alive = async () => {
  const r = await tool.bash({ command: "tasklist | grep -ci fallout4.exe || echo 0", i: "checking game" });
  return parseInt(r.text.trim(), 10) > 0;
};

async function runSession(label) {
  const baseline = lines().length;
  await tool.bash({
    command: `powershell -NoProfile -Command "Start-Process -FilePath '${ctx.GAME}\\\\f4se_loader.exe' -WorkingDirectory '${ctx.GAME}'"`,
    i: `Launching ${label}`,
  });
  let waited = 0;
  while (waited < 420) {
    await sleep(10000);
    waited += 10;
    if (lines().slice(baseline).some((l) => l.includes("behavioral_digest"))) break;
    if (!(await alive())) break;
  }
  const section = lines().slice(baseline);
  const digest = section.find((l) => l.includes("behavioral_digest")) || "MISSING";
  const mapping = section
    .filter((l) => l.includes("refr-lock-numeric-value-to-enum"))
    .map((l) => {
      const m = /input=(-?\d+) result=(-?\d+)/.exec(l);
      return m ? `${m[1]}->${m[2]}` : null;
    })
    .filter(Boolean);
  const labels = section
    .filter((l) => l.includes("melee-attack-speed-label"))
    .map((l) => /input=(\d+) label="([^"]*)"/.exec(l))
    .filter(Boolean)
    .map((m) => `${m[1]}:${m[2]}`);
  const formTypes = section.filter((l) => l.includes("get-form-type-from-string"));
  const formMatches = formTypes.filter((l) => l.includes("match")).length;
  await tool.bash({ command: `powershell -NoProfile -Command "Stop-Process -Name Fallout4 -Force -ErrorAction SilentlyContinue"; sleep 3; tasklist | grep -ci fallout4.exe || echo 0`, i: "stopping game" });
  return { label, digest, mapping: mapping.join(" "), labels: labels.join(" "), formTypes: `${formMatches}/${formTypes.length}`, observedAt: (/(\d{4}-\d{2}-\d{2}T[\d:.]+Z)/.exec(section.find((l) => l.includes("actor-getlevel status=pass")) || "") || [])[1] };
}

const run1 = await runSession("behavioral run 1");
const run2 = await runSession("behavioral run 2");
globalThis.behavioral = { run1, run2 };
display({ run1, run2, digestMatch: run1.digest === run2.digest });

