arguments.command:
cd /f/Fallout4Mapping-1.10.163 && py -3 - <<'PY'
import sqlite3, pefile
from capstone import Cs, CS_ARCH_X86, CS_MODE_64
con = sqlite3.connect('build/research/fo4map-pdb.sqlite'); con.row_factory = sqlite3.Row
pe = pefile.PE('analysis/Fallout4.exe.unpacked.exe', fast_load=True)
img = pe.get_memory_mapped_image(); base = pe.OPTIONAL_HEADER.ImageBase
md = Cs(CS_ARCH_X86, CS_MODE_64); md.detail = True
XMM = {f'xmm{i}' for i in range(8)}
for decl in ('void SetHeading(float a_angle)', 'void SetModelScale(float a_scale)'):
    row = con.execute("""SELECT lf.primary_entry_rva FROM abi_signatures a JOIN logical_functions lf USING(logical_function_id)
                         WHERE a.declaration=?""", (decl,)).fetchone()
    if row is None:
        print(decl, 'not found'); continue
    sites = con.execute("SELECT caller_rva, call_rva FROM calls WHERE image_id=1 AND target_rva=? LIMIT 3", (row[0],)).fetchall()
    print('===', decl, 'rva 0x%X' % row[0], 'sites', len(sites))
    for s in sites:
        rng = con.execute("SELECT begin_rva,end_rva FROM machine_ranges WHERE image_id=1 AND begin_rva<=? AND end_rva>?", (s[1], s[1])).fetchone()
        insns = list(md.disasm(img[rng[0]:rng[1]], base + rng[0]))
        idx = next((i for i, x in enumerate(insns) if x.address - base == s[1]), None)
        if idx is None: continue
        xmm_written = []
        gp_written = []
        for ins in reversed(insns[max(0, idx-12):idx]):
            for op in ins.operands:
                if op.type == 1 and (op.access & 2):
                    name = ins.reg_name(op.reg)
                    if name in XMM and name not in xmm_written: xmm_written.append(name)
                    if name in ('rcx','rdx','r8','r9') and name not in gp_written: gp_written.append(name)
        print('   site 0x%X gp=%s xmm=%s' % (s[1], gp_written, xmm_written))
