// Session: launch, wait for kGameLoaded observations, then drive a save load to
// reach kPostLoadGame and capture the state-dependent getter values.
const ctx = globalThis.pl;
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const lines = () => readFileSync(ctx.LOG, "utf8").split(/\r?\n/);
const alive = async () => {
  const r = await tool.bash({ command: "tasklist | grep -ci fallout4.exe || echo 0", i: "checking game" });
  return parseInt(r.text.trim(), 10) > 0;
};

async function session(label) {
  const baseline = lines().length;
  await tool.bash({
    command: `powershell -NoProfile -Command "Start-Process -FilePath '${ctx.GAME}\\\\f4se_loader.exe' -WorkingDirectory '${ctx.GAME}'"`,
    i: `launching ${label}`,
  });
  // Wait for the kGameLoaded observations first.
  let waited = 0;
  while (waited < 300) {
    await sleep(10000); waited += 10;
    if (lines().slice(baseline).some((l) => l.includes("behavioral_digest event="))) break;
    if (!(await alive())) break;
  }
  const loaded = lines().slice(baseline);

  // Bring the game to the front and load a save through the Continue entry.
  await tool.bash({ command: `powershell -NoProfile -ExecutionPolicy Bypass -File "F:\\Fallout4Mapping-1.10.163\\build\\click_game_window.ps1" -X 316 -Y 106`, i: "clicking continue" });
  await sleep(2500);
  await tool.bash({ command: `powershell -NoProfile -ExecutionPolicy Bypass -File "F:\\Fallout4Mapping-1.10.163\\build\\send_game_key.ps1" -Key ENTER -Count 1`, i: "pressing enter" });

  // Wait for the post-load observations.
  waited = 0;
  let postload = false;
  while (waited < 420) {
    await sleep(15000); waited += 15;
    if (lines().slice(baseline).some((l) => l.includes("behavioral_digest_postload"))) { postload = true; break; }
    if (!(await alive())) break;
  }
  const section = lines().slice(baseline);
  const get = (needle) => section.filter((l) => l.includes(needle));
  const result = {
    label,
    postload,
    loadedLevel: get("actor-getlevel status=pass").map((l) => /return_value=(-?\d+)/.exec(l)?.[1]).filter(Boolean),
    loadedSex: get("actor-getsex status=pass").map((l) => /return_value=(-?\d+)/.exec(l)?.[1]).filter(Boolean),
    postLevel: get("actor-getlevel-postload status=pass").map((l) => /return_value=(-?\d+)/.exec(l)?.[1]).filter(Boolean),
    postSex: get("actor-getsex-postload status=pass").map((l) => /return_value=(-?\d+)/.exec(l)?.[1]).filter(Boolean),
    digests: [...get("behavioral_digest event="), ...get("behavioral_digest_postload")],
    observedAt: (/(\d{4}-\d{2}-\d{2}T[\d:.]+Z)/.exec(get("actor-getlevel status=pass")[0] || "") || [])[1],
  };
  await tool.bash({ command: `powershell -NoProfile -Command "Stop-Process -Name Fallout4 -Force -ErrorAction SilentlyContinue"; sleep 3; tasklist | grep -ci fallout4.exe || echo 0`, i: "stopping" });
  return result;
}

const run1 = await session("postload run 1");
const run2 = await session("postload run 2");
globalThis.postload = { run1, run2 };
display({ run1, run2 });

