const ctx = globalThis.p2;
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const lines = () => readFileSync(ctx.LOG, "utf8").split(/\r?\n/);
const alive = async () => {
  const r = await tool.bash({ command: "tasklist | grep -ci fallout4.exe || echo 0", i: "checking" });
  return parseInt(r.text.trim(), 10) > 0;
};

let waited = 0;
let postload = false;
while (waited < 360) {
  await sleep(15000); waited += 15;
  if (lines().slice(ctx.baseline).some((l) => l.includes("behavioral_digest_postload"))) { postload = true; break; }
  if (!(await alive())) break;
}
const section = lines().slice(ctx.baseline);
const get = (needle) => section.filter((l) => l.includes(needle));
const f4se = (await tool.bash({ command: `grep -c "Loading F4SEPersistentObjectStorage" "C:/Users/micha/Documents/My Games/Fallout4/F4SE/f4se.log" || echo 0`, i: "load marker" })).text.trim();
display({
  postload,
  waited,
  alive: await alive(),
  f4se_load_markers: f4se,
  postLevel: get("actor-getlevel-postload").map((l) => /return_value=(-?\d+)/.exec(l)?.[1]),
  postSex: get("actor-getsex-postload").map((l) => /return_value=(-?\d+)/.exec(l)?.[1]),
  digests: [...get("behavioral_digest event="), ...get("behavioral_digest_postload")],
});

