        groups[-1].append((y, c, x0, x1))
    else:
        groups.append([(y, c, x0, x1)])
print('size', w, h, 'groups', len(groups))
for g in groups[:8]:
    ys = [r[0] for r in g]; x0 = min(r[2] for r in g); x1 = max(r[3] for r in g)
    print('  rows %d-%d w=%d center=(%d,%d)' % (ys[0], ys[-1], x1-x0, (x0+x1)//2, (ys[0]+ys[-1])//2))
PY`,
  i: "analyzing current state",
});
display({ capture: cap.text.trim().slice(0, 100), analysis: py.text.trim() });

